const august14ResearchSpecs = [
  ['knowledge-base-change-evidence', 'Change evidence for virtual assistant knowledge bases', 'A knowledge base stays dependable when every material change has a source, owner, review date, and retirement path.', 'NIST risk guidance and FTC security guidance both support knowing what information is held, who can access it, and how changes or disposal are governed.', 'Compare a dated sample of changed entries with their source records, reviewer disposition, and next review date. Separate a corrected fact from a preference or rewrite.', 'A change log cannot prove that an article is complete, and it does not set a legal retention schedule. The record should show what was checked and what remains uncertain.', ['https://www.nist.gov/cyberframework','https://www.ftc.gov/business-guidance/resources/start-security-guide-business','https://www.nist.gov/privacy-framework'],'knowledge-base-maintenance-for-remote-assistant-teams'],
  ['handoff-context-completeness-study', 'Context completeness in remote assistant handoffs', 'A remote handoff is usable when the next owner can identify the request, current status, evidence, next action, and escalation boundary without reconstructing the story.', 'The SBA connects clear expectations with management, while NIST frameworks emphasize identifying context and responding to risk instead of relying on implied knowledge.', 'Sample handoffs across a defined period and record whether a new owner could act, what clarification was needed, and whether the missing context created delay or risk.', 'A handoff score is local process evidence, not a measure of worker effort or intelligence. Different task types need different minimum fields.', ['https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees','https://www.nist.gov/cyberframework','https://www.cisa.gov/secure-our-world'],'handoff-reliability-in-distributed-teams'],
  ['research-question-scope-for-virtual-assistant-briefs', 'Question scope in virtual assistant research briefs', 'A research brief becomes more useful when one decision question, an eligible evidence set, and an explicit out-of-scope list are defined before collection.', 'The Government Publishing Office supports access to authoritative information, and NIST guidance stresses understanding context and purpose before selecting a control or interpreting risk.', 'Review a sample of briefs for question wording, inclusion rules, source authority, date, unresolved gaps, and the owner decision the brief is meant to inform.', 'A brief-quality review cannot establish that the resulting decision is correct. Legal, financial, medical, or regulated questions need qualified review.', ['https://www.fdlp.gov/','https://www.nist.gov/privacy-framework','https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees'],'research-brief-acceptance-criteria'],
  ['backup-coverage-recovery-evidence', 'Recovery evidence for backup coverage in remote support', 'Backup coverage is credible when a substitute can find the current instructions, use minimum required access, and identify where the owner must take over.', 'CISA emphasizes preparation and recovery, while NIST treats response and recovery as distinct parts of a broader risk-management cycle.', 'Run a bounded, owner-approved exercise using representative low-risk work and record missing instructions, unavailable access, exception routing, and recovery time for the handoff.', 'A controlled exercise cannot predict every outage or authorize production access. It should not copy unnecessary customer data or bypass normal approvals.', ['https://www.cisa.gov/stopransomware','https://www.nist.gov/cyberframework','https://www.ftc.gov/business-guidance/resources/start-security-guide-business'],'backup-coverage-for-remote-assistant-teams'],
  ['owner-review-sampling-for-delegated-work', 'Owner-review sampling for delegated work', 'Owner review is more informative when the sample frame, acceptance rule, exception categories, and follow-up decision are fixed before inspection.', 'The SBA describes management as an ongoing responsibility, and NIST guidance supports identifying and responding to risk through repeatable review rather than assumption.', 'Define eligible work for a stated period, select a representative sample, and record accepted, corrected, pending, and escalated outcomes with the reason for each disposition.', 'A sample is not a workforce-wide performance claim. Small or selected samples can reveal issues but cannot establish a universal rate.', ['https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees','https://www.nist.gov/cyberframework','https://www.cisa.gov/secure-our-world'],'quality-sampling-for-outsourced-administrative-work'],
  ['minimum-access-review-for-content-support', 'Minimum-access review for content support', 'Content support should begin with only the accounts and records required for the first lane, with a named owner for additions and removal.', 'FTC guidance emphasizes protecting information through its lifecycle, while NIST identity guidance separates authentication from authorization.', 'Inventory the first task inputs, map each to a required permission, and review whether the same output can be produced with less access. Record the owner and review date.', 'This study does not determine a company’s legal or contractual obligations. Permission design must reflect the actual systems and sensitive data involved.', ['https://www.ftc.gov/business-guidance/resources/protecting-personal-information-guide-business','https://pages.nist.gov/800-63-3/','https://www.nist.gov/privacy-framework'],'access-governance-for-delegated-operations'],
  ['editorial-source-register-completeness', 'Completeness in editorial source registers', 'A source register is decision-useful when each material claim has a source, access date, scope note, and an explicit unresolved question.', 'The Government Publishing Office provides a pathway to authoritative government information, and NIST risk guidance supports documenting context and limits instead of treating a link as proof by itself.', 'Audit a dated article sample for claim-to-source mapping, source authority, date, definition, and whether the citation actually supports the stated scope.', 'A complete register cannot guarantee factual correctness when a source is wrong, changed, or misinterpreted. Editors still need claim-level judgment.', ['https://www.fdlp.gov/','https://www.nist.gov/cyberframework','https://www.nist.gov/privacy-framework'],'editorial-source-registers-for-daily-articles'],
  ['async-status-evidence-for-remote-assistants', 'Evidence quality in async status updates', 'An async status update reduces coordination cost when progress, blocked work, next action, owner, and evidence are separated.', 'The SBA connects expectations with management, and CISA guidance illustrates why clear preparation and response information matters when conditions change.', 'Compare status updates with the underlying work records for a defined period. Record whether the stated status matched the evidence and whether the next owner could act.', 'Status accuracy is not the same as productivity or business impact. It should not become surveillance or a substitute for direct owner review.', ['https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees','https://www.cisa.gov/secure-our-world','https://www.nist.gov/cyberframework'],'async-status-reporting-for-distributed-assistant-teams'],
  ['work-in-progress-limits-for-remote-support', 'Work-in-progress limits for remote support', 'A small work-in-progress limit can protect review quality when queue pressure, task age, and exception work are visible to the owner.', 'The ILO examines working-time and work-life balance, while NIST risk practices support identifying conditions that make a process harder to control.', 'Compare queue age, correction time, blocked items, and owner review capacity before and after a bounded limit. Keep the task mix and period visible.', 'A queue limit is an operating experiment, not proof of a universally correct workload. It cannot determine employment compliance or individual capacity.', ['https://www.ilo.org/publications/working-time-and-work-life-balance-around-world','https://www.nist.gov/cyberframework','https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees'],'work-in-progress-limits-for-small-remote-teams'],
  ['offboarding-evidence-for-delegated-access', 'Offboarding evidence for delegated access', 'Delegated access is not fully offboarded until the business can identify the account, remove or reassign access, and retain a proportionate record of the decision.', 'FTC guidance addresses lifecycle protection and disposal, while NIST identity guidance distinguishes an identity from its authentication and authorization permissions.', 'Test the offboarding checklist against the actual system inventory and record each removal, reassignment, owner confirmation, and unresolved dependency.', 'A checklist does not replace provider-specific, contractual, employment, or legal advice. Do not retain sensitive credentials as evidence.', ['https://www.ftc.gov/business-guidance/resources/start-security-guide-business','https://pages.nist.gov/800-63-3/','https://www.nist.gov/privacy-framework'],'offboarding-controls-for-delegated-access'],
] as const;

